int _lifecycle_format_topic(const char* prefix, uint32_t id, char* out, size_t out_size) {
    if (!prefix || !out || out_size == 0) {
        return -1;
    }

    char topic[32];
    snprintf(topic, sizeof(topic), "%s-%u", prefix, id);
    topic[sizeof(topic)] = '\0';
    STR_COPY(out, topic);
    return 0;
}

